INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (1,'CMS 全链路冒烟文章','你好 CMS，这是正文内容，用于全文检索测试。','<p>你好 <b>CMS</b>，这是正文内容，用于全文检索测试。</p>',1,NULL,'','',3,0,0,'','cms,冒烟','',NULL,'2026-11-01 02:13:59',2116367567649972226,'admin','改好了','通过','admin','2026-11-01 02:13:59',1,'2026-11-01 02:13:59','2026-11-01 13:41:40',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (13,'统一账号中心 v2.0 发布：一次登录，通达全业务线','v2.0 把认证、授权、单点与多应用管理收敛成一套身份中台，接入方从「各写各的登录」变成「一次对接、全域可用」。','统一账号中心 v2.0 正式发布。这一版的核心目标只有一个：**让身份这件事只做一次**。\n\n## 这一版做了什么\n\n- **统一认证**：账号、密码策略、登录风控集中在一处，密码强度与危险字符校验前后端同一口径。\n- **统一授权**：RBAC 三层模型（应用 → 角色 → 权限），菜单与按钮级权限都可下发到接入方。\n- **单点登录**：基于 OAuth2 授权码 + PKCE，票据一次性兑换，令牌按应用签发、互不越权。\n- **多应用管理**：每个接入应用独立 `appSecret`、独立回调地址、独立权限集，互不干扰。\n\n## 接入方需要做什么\n\n1. 在账号中心注册应用，拿到 `client_id` 与 `appSecret`；\n2. 后端实现一次「票据换令牌」的接口；\n3. 前端把未登录请求导到 `/authorize`，回来落 token 即可。\n\n> 实测：一个标准 Spring Boot + Vue 应用，从注册到跑通单点，**约 30 分钟**。\n\n## 接下来\n\n下一阶段会补齐组织架构同步、SCIM 用户供给与审计日志检索，让身份中台真正覆盖「人从入职到离职」的完整生命周期。',1,2,'微服务,统一认证,OAuth2','',3,1,1,'统一账号中心 v2.0 发布：一次登录，通达全业务线','统一认证,微服务,OAuth2','v2.0 把认证、授权、单点与多应用管理收敛成一套身份中台，接入方从「各写各的登录」变成「一次对接、全域可用」。',NULL,'2026-10-28 09:30:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (14,'为什么我们把 JWT 换成 RS256 非对称签发','从 HS256 共享密钥到 RS256 公私钥分离，换来的是「私钥只在一处、校验方只需公钥」，代价是签名开销与密钥轮换复杂度。','早期为了省事，令牌用的是 HS256——签发和校验共用一把密钥。一旦接入方超过三个，问题就来了：\n\n## HS256 的三个坑\n\n1. **密钥扩散**：每个要校验令牌的服务都得拿到同一把密钥，泄露面随接入方线性增长；\n2. **责任不清**：谁都能签发令牌，日志里分不清是认证中心签的还是某个业务服务签的；\n3. **轮换困难**：换一次密钥，所有服务必须同时重启。\n\n## RS256 怎么解\n\n私钥只存在 auth 服务内，公钥通过 `/api/auth/public/jwks` 暴露（标准 JWKS 格式）。校验方只需拉一次公钥，之后本地验签，**不产生一次网络往返**。\n\n```text\nauth  ──(私钥签名)──> token\ngateway/业务服务 ──(公钥验签)──> 放行 / 401\n```\n\n## 代价与取舍\n\n- 签名比 HMAC 慢一个量级，实测单次签名约 0.6ms——相对一次 HTTP 请求可以忽略；\n- 需要处理密钥轮换：`kid` 标识版本，JWKS 同时保留新旧公钥一个宽限期；\n- 公钥接口必须能被所有校验方访问，且不参与鉴权（否则死锁）。\n\n## 效果\n\n改造后，接入方再也不需要保管任何密钥；令牌伪造的边界收敛到「auth 的私钥文件」这一个点上，安全模型一下清晰了。',2,2,'微服务,统一认证,高可用','',3,0,1,'为什么我们把 JWT 换成 RS256 非对称签发','统一认证,微服务,高可用','从 HS256 共享密钥到 RS256 公私钥分离，换来的是「私钥只在一处、校验方只需公钥」，代价是签名开销与密钥轮换复杂度。',NULL,'2026-10-20 10:10:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (15,'API 网关统一鉴权：从透传到可信头注入','网关验签后剥离伪造头、注入可信身份头，业务服务只读头、不做登录——这是微服务鉴权最省心的一层。','微服务架构里，鉴权放在哪一层，决定了后面所有服务的写法。\n\n## 我们选的那条线\n\n```text\nclient ──> gateway(验签 / 剥离伪造头 / 注入 X-Account-*) ──> service(只读头)\n```\n\n网关做三件事：\n\n1. **验签**：校验 JWT 的签名、过期时间、`aud`（目标应用）；\n2. **剥离**：把客户端自带的 `X-Account-Id` / `X-Account-Name` 等头**全部删除**，防止伪造；\n3. **注入**：验签通过后写入真实身份头，业务服务只信任来自网关的这份数据。\n\n## 为什么不让业务服务自己验\n\n- 每个服务都要拉 JWKS、处理密钥轮换，重复且容易写错；\n- 一旦某个服务漏验，整个链路就破了一个口子；\n- 权限码的比对口径分散，前脚加了按钮后脚忘了加接口。\n\n## 踩过的坑\n\n- **头名大小写**：HTTP 头不区分大小写，但代码里 `getHeader` 区分，统一用小写比较；\n- **内部服务暴露**：业务服务端口只监听内网，公网只能走网关，否则剥离逻辑形同虚设；\n- **本地调试**：开发环境允许直连服务时，必须显式关闭「信任头」开关，避免假头进来。\n\n这层做对之后，新服务接入只需要在 `@Permit` 上声明权限码，剩下什么都不用管。',2,2,'微服务,统一认证,API 网关','',3,0,0,'API 网关统一鉴权：从透传到可信头注入','API 网关,微服务,统一认证','网关验签后剥离伪造头、注入可信身份头，业务服务只读头、不做登录——这是微服务鉴权最省心的一层。',NULL,'2026-10-12 14:20:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (16,'OAuth2 授权码 + PKCE 在多租户 SaaS 的落地','租户隔离不只是数据加个 tenant_id：授权码、令牌、回调地址都要按租户与应用双重绑定。','把 OAuth2 搬进多租户 SaaS，标准流程本身不难，难的是**边界**。\n\n## 三个必须绑死的维度\n\n| 维度 | 绑在哪 | 不绑的后果 |\n| --- | --- | --- |\n| 租户 | 令牌内的 `tenant` 声明 | A 租户的令牌能读 B 租户数据 |\n| 应用 | 令牌 `aud` + 应用密钥 | 博客的令牌能调 CMS 的接口 |\n| 回调地址 | 注册在应用的 `redirect_uri` | 授权码被劫持到第三方站点 |\n\n## PKCE 不是可选项\n\n公共客户端（SPA、小程序）没法安全保存 `client_secret`，必须用 PKCE：\n\n```text\ncode_verifier  = random(43..128)\ncode_challenge = BASE64URL(SHA256(code_verifier))\nGET /authorize?code_challenge=...&code_challenge_method=S256\nPOST /token    code + code_verifier\n```\n\n服务端只保存 `code_challenge`，换票时才校验 `verifier`，即使授权码被截获也无法单独使用。\n\n## 几个容易忽略的点\n\n- **state 必须校验**：它是 CSRF 的唯一防线，不能只生成不回验；\n- **授权码一次性**：换票后立即从存储删除，重放返回 `invalid_grant`；\n- **refresh 绑定客户端**：刷新时同样要校验 `client_id`，否则跨应用越权；\n- **回调地址同源校验**：比较时连端口一起比，`http://a.com` 与 `http://a.com:8080` 是两回事。\n\n按这套做下来，多租户下的令牌越权问题基本可以在协议层被挡住，不用靠业务代码一层层补。',3,4,'统一认证,OAuth2,API 网关','',3,0,1,'OAuth2 授权码 + PKCE 在多租户 SaaS 的落地','OAuth2,统一认证,API 网关','租户隔离不只是数据加个 tenant_id：授权码、令牌、回调地址都要按租户与应用双重绑定。',NULL,'2026-10-05 11:00:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (17,'RBAC 权限模型：菜单、按钮与应用域的三层解耦','权限不是一张平铺的码表。把「能进哪个系统」「能看哪个菜单」「能点哪个按钮」分开建模，才扛得住业务增长。','权限设计最容易犯的错，是把所有东西塞进一张 `permission` 表，然后靠 `code` 字符串前缀区分。\n\n## 我们的三层\n\n1. **应用域（app）**：这个人能进哪几个系统。对应 `account_app` 与令牌里的 `apps`；\n2. **菜单（type=1）**：进入系统后左侧能看到哪些入口，靠 `parentCode` 组织成树；\n3. **按钮（type=2）**：页面里哪些操作可点，码值如 `article:create`、`banner:manage`。\n\n三者**正交**：能进 CMS 不等于能删文章，能看文章列表不等于能审核。\n\n## 鉴权顺序\n\n```text\n401（没令牌） → 403（作用域不是本应用） → 超管旁路 → 比权限码\n```\n\n顺序不能乱：先判身份再判应用，最后才比码。曾经把「比码」放前面，导致跨应用的令牌也能通过按钮校验。\n\n## 几个实践细节\n\n- **权限码前缀带资源名**（`article:` / `banner:`），导入时按 `app + parentCode` 幂等解析；\n- **内置角色禁改禁删**，防止误操作把超管权限弄丢；\n- **删除保护**：角色下有账户时返回 409，而不是默默级联；\n- **前端只做展示控制**，真正的拦截永远在后端 `@Permit`。\n\n## 收益\n\n新增一个应用时，权限体系不需要改模型，只要往 `application` 和 `permission` 里加数据；新增一个按钮时，只要加一条码值并挂到角色上。模型稳定，业务才能快速迭代。',2,2,'微服务,统一认证,RBAC','',3,0,0,'RBAC 权限模型：菜单、按钮与应用域的三层解耦','RBAC,统一认证,微服务','权限不是一张平铺的码表。把「能进哪个系统」「能看哪个菜单」「能点哪个按钮」分开建模，才扛得住业务增长。',NULL,'2026-09-26 15:40:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (18,'单点登录改造实录：12 个登录页收敛为 1 个','一家做工业 SaaS 的客户，12 个子系统各有一套登录。我们用三周把它们收敛成一个入口，顺带统一了密码策略。','## 改造前\n\n12 个子系统，12 套用户表，12 种密码规则（最短的有 6 位纯数字）。用户平均每人记 4 套账号，客服每月处理约 60 起「忘记密码」。\n\n## 三周时间线\n\n**第一周：身份归一**\n用 `username + 手机号` 做唯一键合并，冲突的走人工确认。最终 12 套用户表合并为 1 套，重复账号 3.1%，全部人工核验。\n\n**第二周：协议接入**\n每个子系统后端加一个「票据换令牌」接口，前端把登录页跳转改成 `/authorize`。hash 路由的应用要特别注意：回调地址必须带 `#/sso/callback`，否则授权码落在真实 query 里被路由忽略。\n\n**第三周：收尾**\n统一密码策略（长度 ≥ 8，四类字符至少三类），改密强制下线旧会话，接入方改密统一跳回账号中心。\n\n## 数据变化\n\n| 指标 | 改造前 | 改造后 |\n| --- | --- | --- |\n| 登录入口 | 12 | 1 |\n| 密码规则 | 12 套 | 1 套 |\n| 忘记密码工单/月 | ~60 | ~8 |\n| 新系统接入耗时 | 3~5 人日 | 0.5 人日 |\n\n## 最大的阻力不是技术\n\n是「我这个系统有自己的特殊情况」。最后的做法是：先做两个试点，让其他团队看到接入只需要半天，剩下的是排期问题，不是方案问题。',4,4,'统一认证,OAuth2','',3,0,1,'单点登录改造实录：12 个登录页收敛为 1 个','统一认证,客户案例,OAuth2','一家做工业 SaaS 的客户，12 个子系统各有一套登录。我们用三周把它们收敛成一个入口，顺带统一了密码策略。',NULL,'2026-09-18 09:50:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (19,'令牌校验 P99 从 38ms 降到 4ms 的三次优化','一次线上抖动把网关的令牌校验推到了瓶颈。三次优化分别是：缓存公钥、去掉每次请求的远程调用、把鉴权结果本地化。','## 现象\n\n大促前压测，网关 P99 从 9ms 涨到 38ms，CPU 打满，但业务服务压力并不高——瓶颈在鉴权链路。\n\n## 第一次优化：公钥本地缓存\n\n原来每次验签都要去 auth 拉一次 JWKS。改成进程内缓存 + 5 分钟过期，并按 `kid` 索引。\n\nP99：38ms → 21ms。\n\n## 第二次优化：干掉不必要的 Redis 往返\n\n每个请求都要查一次「会话是否被踢」，一次 Redis RTT 约 1.2ms，高并发下连接池排队放大成 8ms。\n\n改成：令牌里带短期版本号，本地 LRU 缓存「令牌版本 → 有效」5 秒，只有版本变化时才回源。\n\nP99：21ms → 7ms。\n\n## 第三次优化：把权限比对移到本地\n\n按钮权限码原本每次请求都从 Redis 读一遍用户权限集。改为登录时把权限码写进令牌声明（数量可控，约 40 个），网关本地比对。\n\nP99：7ms → 4ms。\n\n## 一些经验\n\n- **先量再改**：每次优化前先看火焰图，不要凭感觉；\n- **缓存要有失效策略**：`kid` 轮换、踢人、权限变更这三种场景必须能立刻生效；\n- **别把令牌塞爆**：权限码超过 100 个就该换方案（改成版本号 + 服务端查表）。\n\n留下来的一个监控指标是「鉴权耗时 P99」，超过 15ms 就告警——这条线帮我们在问题变成故障前抓到过两次。',5,7,'API 网关,可观测性,性能优化','',3,0,0,'令牌校验 P99 从 38ms 降到 4ms 的三次优化','性能优化,可观测性,API 网关','一次线上抖动把网关的令牌校验推到了瓶颈。三次优化分别是：缓存公钥、去掉每次请求的远程调用、把鉴权结果本地化。',NULL,'2026-09-10 16:30:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (20,'微服务雪崩防护：限流、熔断与降级的分层设计','雪崩从来不是某一个服务挂了，而是调用链上的超时与重试叠加。分层设防，才能让故障止步于边界。','## 雪崩是怎么发生的\n\n一个慢查询让 A 服务的 P99 从 50ms 变成 2s，上游 B 的重试策略是 3 次，于是 A 的流量瞬间变成 4 倍；B 的线程池被打满，C 开始超时……十分钟后整条链路都在报错，但根因只是一个没加索引的 `order by`。\n\n## 分层设防\n\n**接入层：限流**\n按 IP + 用户维度限流，把异常流量挡在网关，不让它进入业务服务。\n\n**服务间：超时 + 熔断**\n超时必须显式设置且逐层递减（网关 3s → 服务 2s → 下游 1s），否则上游等下游等到天荒地老。\n\n```yaml\nresilience4j.circuitbreaker:\n  failureRateThreshold: 50\n  slowCallDurationThreshold: 1s\n  slidingWindowSize: 20\n```\n\n**数据层：隔离**\n慢查询走独立连接池，避免拖垮核心交易；对非核心统计类查询直接降级为缓存结果。\n\n## 降级的底线\n\n降级不是「返回空」，而是「返回一个用户能理解的、业务可接受的兜底」：\n\n- 推荐位挂了 → 返回默认运营配置；\n- 头像服务挂了 → 返回首字母占位；\n- 权限服务挂了 → **拒绝**，不能默认放行。\n\n最后这条最重要：可用性再差，也不能因为降级把不该给的数据给出去。',3,2,'微服务,Spring Cloud,高可用','',3,0,0,'微服务雪崩防护：限流、熔断与降级的分层设计','高可用,微服务,Spring Cloud','雪崩从来不是某一个服务挂了，而是调用链上的超时与重试叠加。分层设防，才能让故障止步于边界。',NULL,'2026-09-02 10:25:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
INSERT IGNORE INTO `cms_article` (`id`, `title`, `summary`, `content`, `category_id`, `tag_id`, `tag`, `cover`, `status`, `pinned`, `recommended`, `seo_title`, `seo_keywords`, `seo_description`, `publish_at`, `published_at`, `author_id`, `author_name`, `submit_note`, `audit_note`, `auditor_name`, `audit_at`, `deleted`, `created_at`, `updated_at`, `approval_instance_id`) VALUES (21,'统一账号中心接入 FAQ：10 个高频问题','整理自接入群里的真实提问：回调地址怎么配、hash 路由为什么拿不到 code、令牌过期要不要刷新、超管为什么绕过权限……','## 1. 回调地址（redirect_uri）怎么写？\n\n必须与注册时的值**完全一致**，包括协议、域名、端口和路径。前端在 `localhost:5173`、后端在 `127.0.0.1:8080` 是跨源，不算一致。\n\n## 2. 为什么我的 hash 路由应用拿不到 code？\n\n`?code=` 落在真实 query 上，而 hash 路由只读 `#` 之后的部分。回调地址要写成 `http://host/#/sso/callback`。\n\n## 3. 令牌过期了要自己刷新吗？\n\naccess token 默认 2 小时。前端拦截 401，用 refresh token 换新令牌；refresh 也要校验 `client_id`，不能跨应用使用。\n\n## 4. 为什么超管能进但我不能？\n\n超管在 `@Permit` 上是旁路放行的。检查你的角色是否挂上了对应的权限码，以及权限码的 `app_code` 是不是当前应用。\n\n## 5. appSecret 能放前端吗？\n\n绝对不能。换票必须由后端发起，前端只拿 code 交给自家后端。\n\n## 6. 本地开发一直跳登录页？\n\n多半是 origin 不匹配。注册的 `base_url` 是 `localhost:5178`，你用 `127.0.0.1:5178` 访问就是另一个 origin。\n\n## 7. 密码规则是什么？\n\n长度 ≥ 8，大写/小写/数字/特殊四类至少三类，并过滤危险字符。前后端同一口径，前端实时提示，后端兜底校验。\n\n## 8. 怎么批量导入权限？\n\n`POST /api/applications/{code}/permissions/import`，按 `app + parentCode` 幂等解析，重复执行不会产生脏数据。\n\n## 9. 换票接口返回 500？\n\n先看应用密钥有没有注入到环境变量，再确认 `redirect_uri` 与换票时传的是否一致。\n\n## 10. 怎么排查某个用户进不去？\n\n按顺序查：`/api/auth/session` 的 `appList` 里有没有目标应用 → 令牌 `apps` 是否包含 → 用户角色是否绑定 → 角色是否有对应权限码。',1,4,'统一认证,OAuth2,RBAC','',3,0,0,'统一账号中心接入 FAQ：10 个高频问题','统一认证,OAuth2,RBAC','整理自接入群里的真实提问：回调地址怎么配、hash 路由为什么拿不到 code、令牌过期要不要刷新、超管为什么绕过权限……',NULL,'2026-08-25 11:15:00',2116367567649972226,'admin','','',NULL,NULL,0,'2026-11-01 13:43:37','2026-11-06 17:05:11',NULL);
